INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ヒヨリ", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 100101, "獣人族", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 44, "人助け、応援", 155, 2, "東山奈央", 27, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ユイ", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 100201, "ヒューマン", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 47, "料理、人間観察", 158, 2, "種田梨沙", 5, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "レイ", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 100301, "魔族", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 46, "読書、乗馬、お茶", 163, 2, "早見沙織", 12, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミソギ", 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, 100401, "ヒューマン", "リトルリリカル", "探検好きのイタズラっ子", 27, "いたずら、探検", 128, 5, "諸星すみれ", 10, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マツリ", 12, "？？？", 0, 100501, "獣人族", "王宮騎士団（NIGHTMARE）", "ヒーローに憧れる騎士見習いの少女", 40, "ヒーローごっこ", 146, 8, "下田麻美", 25, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アカリ", 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, 100601, "魔族", "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", 42, "サックス", 150, 7, "浅倉杏美", 22, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ミヤコ", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 100701, "魔族", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 32, "プリンを食べること", 130, 7, "雨宮天", 23, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ユキ", 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, 100801, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", 40, "鏡で自分を見ること", 150, 15, "大空直美", 10, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "アンナ", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 100901, "魔族", "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 45, "小説執筆", 159, 13, "髙野麻美", 5, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マホ", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 101001, "獣人族", "自警団（カォン）", "マホマホ王国のプリンセス", 42, "空想、ぬいぐるみ集め", 155, 10, "内田真礼", 22, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "リノ", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 101101, "ヒューマン", "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 44, "お裁縫", 156, 3, "阿澄佳奈", 25, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ハツネ", 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, 101201, "エルフ", "フォレスティエ", "みんなのために超能力を使う眠り姫", 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 156, 6, "大橋彩香", 24, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ナナカ", 18, "", 0, 101301, "魔族", "トワイライトキャラバン", "オタク全開な魔法少女", 55, "読書、魔法", 166, 13, "佳村はるか", 21, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "カスミ", 15, "test", 0, 101401, "獣人族", "自警団（カォン）", "頭脳明晰な美少女名探偵", 41, "読書、推理", 152, 10, "水瀬いのり", 3, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミサト", 21, "test", 0, 101501, "エルフ", "フォレスティエ", "母性溢れる優しいみんなの「ミサト先生」", 54, "絵本作り", 165, 6, "國府田マリ子", 5, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズナ", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 101601, "魔族", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 48, "ファッション", 167, 14, "上坂すみれ", 10, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "カオリ", 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, 101701, "獣人族", "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", 53, "踊り、空手", 158, 10, "高森奈津美", 7, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "イオ", 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 101801, "魔族", "ルーセント学院", "多くの男性を魅了する無垢な女教師", 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 162, 14, "伊藤静", 14, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミミ", 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, 102001, "獣人族", "リトルリリカル", "お歌もにんじんも、ウサギさんも大好き♪", 21, "かわいいもの集め", 117, 5, "日高里菜", 3, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "クルミ", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 102101, "ヒューマン", "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", 40, "観劇、おままごと", 150, 9, "植田佳奈", 9, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヨリ", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 102201, "魔族", "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 40, "ゲーム全般", 150, 7, "原紗友里", 22, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "アヤネ", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 102301, "ヒューマン", "サレンディア救護院", "ぷうきちといつも一緒！", 38, "屋内でできる遊び", 148, 9, "芹澤優", 10, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズメ", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 102501, "ヒューマン", "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", 43, "ご奉仕", 154, 9, "悠木碧", 12, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "リン", 17, "test", 0, 102601, "獣人族", "牧場（エリザベスパーク）", "遊びと睡眠が何より大事なぐうたら娘", 42, "あんパン", 144, 11, "小岩井ことり", 1, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "エリコ", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 102701, "魔族", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 43, "実験、裁縫、料理", 154, 13, "橋本ちなみ", 30, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "サレン", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 102801, "エルフ", "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", 43, "経営、お茶会", 156, 9, "堀江由衣", 4, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ノゾミ", 17, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", 0, 102901, "ヒューマン", "カルミナ", "歌って踊れる大人気アイドル", 40, "舞台鑑賞、ダンス", 157, 4, "日笠陽子", 24, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ニノン", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 103001, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 51, "忍法開発", 163, 15, "佐藤聡美", 31, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "シノブ", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 103101, "魔族", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 42, "占い", 157, 7, "大坪由佳", 22, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "アキノ", 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, 103201, "ヒューマン", "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", 45, "慈善事業", 157, 12, "松嵜麗", 12, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "マヒル", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 103301, "ヒューマン", "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 35, "漫才", 142, 11, "新田恵海", 3, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ユカリ", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 103401, "エルフ", "メルクリウス財団", "純情でほっとけない大人の女性", 55, "ウインドーショッピング", 164, 12, "今井麻美", 16, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キョウカ", 8, "test", 0, 103601, "エルフ", "リトルリリカル", "礼儀正しくしっかり者のちびっ子優等生", 21, "お勉強", 118, 5, "小倉唯", 2, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "トモ", 13, "test", 0, 103701, "ヒューマン", "王宮騎士団（NIGHTMARE）", "義理堅くてからかい好きな剣術少女", 43, "剣術、年長者をからかう", 149, 8, "茅原実里", 11, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "シオリ", 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, 103801, "獣人族", "牧場（エリザベスパーク）", "読書が趣味の病弱少女", 40, "読書、お散歩", 153, 11, "小清水亜美", 3, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "アオイ", 13, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", 0, 104001, "エルフ", "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", 44, "友達作りのイメトレ", 158, 6, "花澤香菜", 6, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "チカ", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 104201, "ヒューマン", "カルミナ", "人々を守るために歌う、唱喚士の少女", 46, "各種楽器", 163, 4, "福原綾香", 3, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マコト", 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, 104301, "獣人族", "自警団（カォン）", "男勝りで情に厚いワイルド娘", 54, "お菓子作り", 168, 10, "小松未可子", 9, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "イリヤ", "??", "test", 0, 104401, "魔族", "悪魔偽王国軍（ディアボロス）", "かつては夜を支配した最強の吸血鬼", 50, "世界征服", 172, 7, "丹下桜", 5, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "クウカ", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 104501, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 49, "小説を読むこと", 157, 15, "長妻樹里", 19, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "タマキ", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 104601, "獣人族", "メルクリウス財団", "弱きを助け強きをくじく猫娘", 48, "猫とたわむれること", 158, 12, "沼倉愛美", 1, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ジュン", 25, "？？？", 0, 104701, "ヒューマン", "王宮騎士団（NIGHTMARE）", "素顔を見せない冷静沈着な女性騎士", 50, "格闘技、湯浴み", 171, 8, "川澄綾子", 25, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミフユ", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 104801, "ヒューマン", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 49, "傭兵などのアルバイト", 163, 12, "田所あずさ", 11, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "シズル", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 104901, "ヒューマン", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 54, "家事全般", 168, 3, "生天目仁美", 24, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ミサキ", 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, 105001, "魔族", "ルーセント学院", "ちょっとおませな恋に恋する女の子", 22, "ファッション誌鑑賞、コスメ集め", 120, 14, "久野美咲", 3, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ミツキ", 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, 105101, "ヒューマン", "トワイライトキャラバン", "実験が趣味の危険な科学者", 53, "研究、実験", 166, 13, "三石琴乃", 7, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "リマ", 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 0, 105201, "獣人族", "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", 100, "毛繕い、お喋り", 150, 11, "徳井青空", 14, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "モニカ", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 105301, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", 33, "お菓子屋通い", 140, 15, "辻あゆみ", 28, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ツムギ", 14, "test", 0, 105401, "ヒューマン", "カルミナ", "ファッション大好きなキュートガール", 45, "裁縫", 153, 4, "木戸衣吹", 7, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アユミ", 16, "test", 0, 105501, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "どこまでも一途に慕う、純情乙女", 43, "観察", 155, 15, "大関英里", 7, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ルカ", 25, "test", 0, 105601, "ヒューマン", "トワイライトキャラバン", "人情味溢れる粋でいなせな「姉御」", 54, "釣り", 167, 13, "佐藤利奈", 11, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ジータ", 17, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", 0, 105701, "ヒューマン", "？？？", "空への冒険を夢見る騎空士の少女", 45, "冒険、おしゃべり", 156, "", "金元寿子", 10, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ペコリーヌ", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 105801, "ヒューマン", "美食殿", "いつも元気な腹ペコ少女", 46, "食べ歩き、料理", 156, 1, "M・A・O", 31, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "コッコロ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 105901, "エルフ", "美食殿", "主を慕う、小さなガイド役", 35, "瞑想、動植物の飼育", 140, 1, "伊藤美来", 11, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キャル", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 106001, "獣人族", "美食殿", "行き倒れの謎のネコミミ魔法使い", 39, "猫と遊ぶ", 152, 1, "立花理香", 2, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ムイミ", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 106101, "ヒューマン", "？？？", "さまよえる謎の少女", 40, "冒険、思い出話", 148, "", "潘めぐみ", 11, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アリサ", 15, "", 0, 106301, "エルフ", "？？？", "森番を目指すエルフの少女", 42, "キレイな葉っぱを集めること", 155, "", "優木かな", 17, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "シェフィ", 14, "", 0, 106401, "ドラゴン族", "美食殿", "記憶喪失のドラゴン娘", "???", "読書、ストレッチ", 147, 1, "近藤玲奈", 14, 12);
