INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "イノリ", 13, "", 0, 106601, "ドラゴン族", "ドラゴンズネスト", "口が達者なヘタレドラゴン", "???", "ゲーム", 145, 17, "藤田茜", 29, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ホマレ", 25, "", 0, 106701, "ドラゴン族", "ドラゴンズネスト", "妖しい微笑で全てを見透かす臥竜の頭領", "???", "絵画、読書", 168, 17, "大西沙織", 17, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ラビリスタ", 25, "", 0, 106801, "ヒューマン", "ラビリンス", "秘密結社ラビリンスの『迷宮女王』", "??", "人間観察", 160, 3, "沢城みゆき", 25, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "カイザーインサイト", 29, "", 0, 106901, "獣人族", "？？？", "謎に包まれたランドソルの主", "??", "占い、支配", 166, "", "蒼井翔太", 1, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ネネカ", 24, "", 0, 107001, "エルフ", "？？？", "研究所に隠れ住む物静かなお姉さん", "??", "物真似、芸術鑑賞", 149, "", "井口裕香", 24, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "クリスティーナ", 27, "", 0, 107101, "ヒューマン", "王宮騎士団（NIGHTMARE）", "傍若無人な王宮騎士団副団長", "??", "強敵との闘争", 165, 8, "たかはし智秋", 7, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ペコリーヌ（サマー）", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 107501, "ヒューマン", "美食殿", "いつも元気な腹ペコ少女", 46, "食べ歩き、料理", 156, 1, "M・A・O", 31, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "コッコロ（サマー）", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 107601, "エルフ", "美食殿", "主を慕う、小さなガイド役", 35, "瞑想、動植物の飼育", 140, 1, "伊藤美来", 11, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズメ（サマー）", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 107701, "ヒューマン", "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", 43, "ご奉仕", 154, 9, "悠木碧", 12, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キャル（サマー）", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 107801, "獣人族", "美食殿", "行き倒れの謎のネコミミ魔法使い", 39, "猫と遊ぶ", 152, 1, "立花理香", 2, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "タマキ（サマー）", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 107901, "獣人族", "メルクリウス財団", "弱きを助け強きをくじく猫娘", 48, "猫とたわむれること", 158, 12, "沼倉愛美", 1, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミフユ（サマー）", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 108001, "ヒューマン", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 49, "傭兵などのアルバイト", 163, 12, "田所あずさ", 11, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "シノブ（ハロウィン）", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 108101, "魔族", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 42, "占い", 157, 7, "大坪由佳", 22, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ミヤコ（ハロウィン）", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 108201, "魔族", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 32, "プリンを食べること", 130, 7, "雨宮天", 23, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ミサキ（ハロウィン）", 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", 0, 108301, "魔族", "ルーセント学院", "ちょっとおませな恋に恋する女の子", 22, "ファッション誌鑑賞、コスメ集め", 120, 14, "久野美咲", 3, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "チカ（クリスマス）", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 108401, "ヒューマン", "カルミナ", "人々を守るために歌う、唱喚士の少女", 46, "各種楽器", 163, 4, "福原綾香", 3, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "クルミ（クリスマス）", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 108501, "ヒューマン", "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", 40, "観劇、おままごと", 150, 9, "植田佳奈", 9, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "アヤネ（クリスマス）", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 108601, "ヒューマン", "サレンディア救護院", "ぷうきちといつも一緒！", 38, "屋内でできる遊び", 148, 9, "芹澤優", 10, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ヒヨリ（ニューイヤー）", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 108701, "獣人族", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 44, "人助け、応援", 155, 2, "東山奈央", 27, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ユイ（ニューイヤー）", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 108801, "ヒューマン", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 47, "料理、人間観察", 158, 2, "種田梨沙", 5, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "レイ（ニューイヤー）", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 108901, "魔族", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 46, "読書、乗馬、お茶", 163, 2, "早見沙織", 12, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "エリコ（バレンタイン）", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 109001, "魔族", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 43, "実験、裁縫、料理", 154, 13, "橋本ちなみ", 30, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "シズル（バレンタイン）", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 109101, "ヒューマン", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 54, "家事全般", 168, 3, "生天目仁美", 24, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "アン", 17, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", 0, 109201, "ヒューマン", "？？？", "英霊と契約を結んだマナリアの天才王女", 55, "読書", 156, "", "日笠陽子", 1, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ルゥ", 16, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", 0, 109301, "ヒューマン", "？？？", "マナリア魔法学院の新入生", 45, "食べること、眠ること", 144, "", "こやまきみこ", 4, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "グレア", 17, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", 0, 109401, "半人半竜", "？？？", "人を超越した力を有す心優しい竜姫", 67, "ピアノ", 167, "", "福原綾香", 3, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "クウカ（オーエド）", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 109501, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 49, "小説を読むこと", 157, 15, "長妻樹里", 19, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ニノン（オーエド）", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 109601, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 51, "忍法開発", 163, 15, "佐藤聡美", 31, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("?", "レム", 17, "", 0, 109701, "鬼族", "？？？", "鬼がかりの万能妹メイド", "??", "演劇鑑賞、詩文", 154, "", "水瀬いのり", 2, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("?", "ラム", 17, "", 0, 109801, "鬼族", "？？？", "毒舌系鬼姉メイド", "??", "読書", 154, "", "村川梨衣", 2, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("?", "エミリア", "??", "", 0, 109901, "ハーフエルフ", "？？？", "銀髪のおっとりハーフエルフ", "??", "パックの毛繕い、勉強", 164, "", "高橋李依", 23, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズナ（サマー）", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 110001, "魔族", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 48, "ファッション", 167, 14, "上坂すみれ", 10, 4);
