INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ぺコリーヌ（ニューイヤー）", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", 0, 111801, "ヒューマン", "美食殿", "いつも元気な腹ペコ少女", 46, "食べ歩き、料理", 156, 1, "M・A・O", 31, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "コッコロ（ニューイヤー）", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 111901, "エルフ", "美食殿", "主を慕う、小さなガイド役", 35, "瞑想、動植物の飼育", 140, 1, "伊藤美来", 11, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キャル（ニューイヤー）", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 112001, "獣人族", "美食殿", "行き倒れの謎のネコミミ魔法使い", 39, "猫と遊ぶ", 152, 1, "立花理香", 2, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズメ（ニューイヤー）", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", 0, 112101, "ヒューマン", "サレンディア救護院", "お嬢さまのためにがんばるドジっ娘メイド", 43, "ご奉仕", 154, 9, "悠木碧", 12, 12);
