INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "シオリ（マジカル）", 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", 0, 112301, "獣人族", "牧場（エリザベスパーク）", "読書が趣味の病弱少女", 40, "読書、お散歩", 153, 11, "小清水亜美", 3, 11);
