INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "マヒル（レンジャー）", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 112801, "ヒューマン", "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 35, "漫才", 142, 11, "新田恵海", 3, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "リノ（ワンダー）", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 112901, "ヒューマン", "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 44, "お裁縫", 156, 3, "阿澄佳奈", 25, 8);
