INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "アンナ（サマー）", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 113201, "魔族", "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 45, "小説執筆", 159, 13, "髙野麻美", 5, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ナナカ（サマー）", 18, "", 0, 113301, "魔族", "トワイライトキャラバン", "オタク全開な魔法少女", 55, "読書、魔法", 166, 13, "佳村はるか", 21, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ハツネ（サマー）", 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", 0, 113401, "エルフ", "フォレスティエ", "みんなのために超能力を使う眠り姫", 46, "妹と遊ぶこと、二度寝、昼寝、早寝", 156, 6, "大橋彩香", 24, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミサト（サマー）", 21, "", 0, 113501, "エルフ", "フォレスティエ", "母性溢れる優しいみんなの「ミサト先生」", 54, "絵本作り", 165, 6, "國府田マリ子", 5, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ジュン（サマー）", 25, "", 0, 113601, "ヒューマン", "王宮騎士団（NIGHTMARE）", "素顔を見せない冷静沈着な女性騎士", 50, "格闘技、湯浴み", 171, 8, "川澄綾子", 25, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "アカリ（エンジェル）", 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", 0, 113701, "魔族", "悪魔偽王国軍（ディアボロス）", "甘え上手なみんなの人気者", 42, "サックス", 150, 7, "浅倉杏美", 22, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヨリ（エンジェル）", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 113801, "魔族", "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 40, "ゲーム全般", 150, 7, "原紗友里", 22, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ツムギ（ハロウィン）", 14, "", 0, 113901, "ヒューマン", "カルミナ", "ファッション大好きなキュートガール", 45, "裁縫", 153, 4, "木戸衣吹", 7, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "レイ（ハロウィン）", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 114001, "魔族", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 46, "読書、乗馬、お茶", 163, 2, "早見沙織", 12, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マツリ（ハロウィン）", 12, "", 0, 114101, "獣人族", "王宮騎士団（NIGHTMARE）", "ヒーローに憧れる騎士見習いの少女", 40, "ヒーローごっこ", 146, 8, "下田麻美", 25, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "モニカ（マジカル）", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 114201, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", 33, "お菓子屋通い", 140, 15, "辻あゆみ", 28, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "トモ（マジカル）", 13, "", 0, 114301, "ヒューマン", "王宮騎士団（NIGHTMARE）", "義理堅くてからかい好きな剣術少女", 43, "剣術、年長者をからかう", 149, 8, "茅原実里", 11, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "アキノ（クリスマス）", 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", 0, 114401, "ヒューマン", "メルクリウス財団", "一人前の商人を目指すパワフルお嬢様", 45, "慈善事業", 157, 12, "松嵜麗", 12, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "サレン（クリスマス）", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 114501, "エルフ", "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", 43, "経営、お茶会", 156, 9, "堀江由衣", 4, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ユカリ（クリスマス）", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 114601, "エルフ", "メルクリウス財団", "純情でほっとけない大人の女性", 55, "ウインドーショッピング", 164, 12, "今井麻美", 16, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ムイミ（ニューイヤー）", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 114701, "ヒューマン", "？？？", "さまよえる謎の少女", 40, "冒険、思い出話", 148, "", "潘めぐみ", 11, 8);
