INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "コッコロ（儀装束）", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", 0, 115501, "エルフ", "美食殿", "主を慕う、小さなガイド役", 35, "瞑想、動植物の飼育", 140, 1, "伊藤美来", 11, 5);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ユイ（儀装束）", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 115601, "ヒューマン", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 47, "料理、人間観察", 158, 2, "種田梨沙", 5, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "カスミ（サマー）", 15, "", 0, 115701, "獣人族", "自警団（カォン）", "頭脳明晰な美少女名探偵", 41, "読書、推理", 152, 10, "水瀬いのり", 3, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "リマ（シンデレラ）", 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", 0, 115801, "獣人族", "牧場（エリザベスパーク）", "乙女チックなもふもふアニマル", 100, "毛繕い、お喋り", 150, 11, "徳井青空", 14, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マコト（シンデレラ）", 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", 0, 115901, "獣人族", "自警団（カォン）", "男勝りで情に厚いワイルド娘", 54, "お菓子作り", 168, 10, "小松未可子", 9, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "マホ（シンデレラ）", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", 0, 116001, "獣人族", "自警団（カォン）", "マホマホ王国のプリンセス", 42, "空想、ぬいぐるみ集め", 155, 10, "内田真礼", 22, 9);
