INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "タマキ（作業服）", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 116801, "獣人族", "メルクリウス財団", "弱きを助け強きをくじく猫娘", 48, "猫とたわむれること", 158, 12, "沼倉愛美", 1, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミフユ（作業服）", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", 0, 116901, "ヒューマン", "メルクリウス財団", "仕事も私事も効率優先な傭兵少女", 49, "傭兵などのアルバイト", 163, 12, "田所あずさ", 11, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "エリコ（サマー）", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", 0, 117001, "魔族", "トワイライトキャラバン", "運命の相手に一途すぎる乙女", 43, "実験、裁縫、料理", 154, 13, "橋本ちなみ", 30, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "シズル（サマー）", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", 0, 117101, "ヒューマン", "ラビリンス", "お姉ちゃんがお世話してあげるからねっ！", 54, "家事全般", 168, 3, "生天目仁美", 24, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ノゾミ（サマー）", 17, "", 0, 117201, "ヒューマン", "カルミナ", "歌って踊れる大人気アイドル", 40, "舞台鑑賞、ダンス", 157, 4, "日笠陽子", 24, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "チカ（サマー）", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", 0, 117301, "ヒューマン", "カルミナ", "人々を守るために歌う、唱喚士の少女", 46, "各種楽器", 163, 4, "福原綾香", 3, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ツムギ（サマー）", 14, "", 0, 117401, "ヒューマン", "カルミナ", "ファッション大好きなキュートガール", 45, "裁縫", 153, 4, "木戸衣吹", 7, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ミツキ（オーエド）", 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", 0, 117501, "ヒューマン", "トワイライトキャラバン", "実験が趣味の危険な科学者", 53, "研究、実験", 166, 13, "三石琴乃", 7, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ユキ（オーエド）", 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", 0, 117601, "エルフ", "ヴァイスフリューゲル　ランドソル支部", "ボクは誰よりも美しい", 40, "鏡で自分を見ること", 150, 15, "大空直美", 10, 10);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "カオリ（ハロウィン）", 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", 0, 117701, "獣人族", "自警団（カォン）", "いつでも「なんくるないさ～」な天然娘", 53, "踊り、空手", 158, 10, "高森奈津美", 7, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ニノン（ハロウィン）", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", 0, 117801, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "トーゴクの神秘、オシエテクダサイ！", 51, "忍法開発", 163, 15, "佐藤聡美", 31, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズナ（ハロウィン）", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 117901, "魔族", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 48, "ファッション", 167, 14, "上坂すみれ", 10, 4);
