INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "イオ（ノワール）", 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", 0, 119001, "魔族", "ルーセント学院", "多くの男性を魅了する無垢な女教師", 52, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", 162, 14, "伊藤静", 14, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "クウカ（ノワール）", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 119101, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 49, "小説を読むこと", 157, 15, "長妻樹里", 19, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "マヒル（クリスマス）", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", 0, 119201, "ヒューマン", "牧場（エリザベスパーク）", "みんなを笑顔にするお笑い牧場主", 35, "漫才", 142, 11, "新田恵海", 3, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "リノ（クリスマス）", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", 0, 119301, "ヒューマン", "ラビリンス", "人懐っこくてマシンガントークな妹系少女", 44, "お裁縫", 156, 3, "阿澄佳奈", 25, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "ミヤコ（クリスマス）", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", 0, 119901, "魔族", "悪魔偽王国軍（ディアボロス）", "プリン大好きゴースト娘", 32, "プリンを食べること", 130, 7, "雨宮天", 23, 1);
