INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "クルミ（ステージ）", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", 0, 121301, "ヒューマン", "サレンディア救護院", "泣き虫で臆病な守ってあげたい女の子", 40, "観劇、おままごと", 150, 9, "植田佳奈", 9, 6);
