INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "アンナ（パイレーツ）", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", 0, 121901, "魔族", "トワイライトキャラバン", "前世を信じる中二病患者、「疾風の冥姫」", 45, "小説執筆", 159, 13, "髙野麻美", 5, 7);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "シノブ（パイレーツ）", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 122001, "魔族", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 42, "占い", 157, 7, "大坪由佳", 22, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "アオイ（キャンプ）", 13, "", 0, 122101, "エルフ", "フォレスティエ", "「友達」に憧れる、エルフの森の女の子", 44, "友達作りのイメトレ", 158, 6, "花澤香菜", 6, 6);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ユカリ（キャンプ）", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", 0, 122201, "エルフ", "メルクリウス財団", "純情でほっとけない大人の女性", 55, "ウインドーショッピング", 164, 12, "今井麻美", 16, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "ヴァンピィ", "??", "", 0, 122301, "魔族", "？？？", "けんぞくのご主人様", 41, "お散歩、お料理", 149, "", "釘宮理恵", 6, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ヒヨリ（サマー）", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 122401, "獣人族", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 44, "人助け、応援", 155, 2, "東山奈央", 27, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "レイ（サマー）", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", 0, 122501, "魔族", "トゥインクルウィッシュ", "クールで何事にも真っ直ぐな剣士", 46, "読書、乗馬、お茶", 163, 2, "早見沙織", 12, 1);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ユイ（サマー）", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 122601, "ヒューマン", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 47, "料理、人間観察", 158, 2, "種田梨沙", 5, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キョウカ（サマー）", 8, "", 0, 122701, "エルフ", "リトルリリカル", "礼儀正しくしっかり者のちびっ子優等生", 21, "お勉強", 118, 5, "小倉唯", 2, 2);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミソギ（サマー）", 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", 0, 122801, "ヒューマン", "リトルリリカル", "探検好きのイタズラっ子", 27, "いたずら、探検", 128, 5, "諸星すみれ", 10, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ミミ（サマー）", 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", 0, 122901, "獣人族", "リトルリリカル", "お歌もにんじんも、ウサギさんも大好き♪", 21, "かわいいもの集め", 117, 5, "日高里菜", 3, 4);
