INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("B", "アヤネ（エクスプローラー）", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", 0, 123201, "ヒューマン", "サレンディア救護院", "ぷうきちといつも一緒！", 38, "屋内でできる遊び", 148, 9, "芹澤優", 10, 5);
