INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ヨリ（クリスマス）", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", 0, 124101, "魔族", "悪魔偽王国軍（ディアボロス）", "人見知りであまのじゃくな女の子", 40, "ゲーム全般", 150, 7, "原紗友里", 22, 11);
