INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ムイミ（リベレイター）", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", 0, 125001, "ヒューマン", "？？？", "さまよえる謎の少女", 40, "冒険、思い出話", 148, "", "潘めぐみ", 11, 8);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "タマキ（カフェ）", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", 0, 125101, "獣人族", "メルクリウス財団", "弱きを助け強きをくじく猫娘", 48, "猫とたわむれること", 158, 12, "沼倉愛美", 1, 3);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "モニカ（カフェ）", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", 0, 125201, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "見た目も中身もお子ちゃまな異国の軍人", 33, "お菓子屋通い", 140, 15, "辻あゆみ", 28, 7);
