INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ランファ（サマー）", 20, "", 0, 126901, "魔族", "レイジ・レギオン", "静寂を求め歌う陰気少女", 53, "歌、読書、詩を書くこと", 165, 19, "原田彩楓", 28, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "クウカ（サマー）", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", 0, 127001, "ヒューマン", "ヴァイスフリューゲル　ランドソル支部", "妄想大好き！　ほんとは照れ屋な女の子", 49, "小説を読むこと", 157, 15, "長妻樹里", 19, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "シノブ（サマー）", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", 0, 127101, "魔族", "悪魔偽王国軍（ディアボロス）", "占いが得意な霊能少女", 42, "占い", 157, 7, "大坪由佳", 22, 12);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "キャル（編入生）", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", 0, 127201, "獣人族", "美食殿", "行き倒れの謎のネコミミ魔法使い", 39, "猫と遊ぶ", 152, 1, "立花理香", 2, 9);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "スズナ（編入生）", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", 0, 127301, "魔族", "ルーセント学院", "天真爛漫で人気者のカリスマモデル", 48, "ファッション", 167, 14, "上坂すみれ", 10, 4);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "サレン（サラサリア）", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", 0, 127501, "エルフ", "サレンディア救護院", "救護院を経営する優しい庶民派お嬢様", 43, "経営、お茶会", 156, 9, "堀江由衣", 4, 10);
