INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "イノリ（ニューイヤー）", 13, "", 0, 128301, "ドラゴン族", "ドラゴンズネスト", "口が達者なヘタレドラゴン", "???", "ゲーム", 145, 17, "藤田茜", 29, 9);
