INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("AB", "カスミ（ニューイヤー）", 15, "", 0, 128501, "獣人族", "自警団（カォン）", "頭脳明晰な美少女名探偵", 41, "読書、推理", 152, 10, "水瀬いのり", 3, 11);
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("A", "ヒヨリ（アストラル）", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", 0, 128701, "獣人族", "トゥインクルウィッシュ", "人助けが大好き！　前向き格闘娘", 44, "人助け、応援", 155, 2, "東山奈央", 27, 8);
