INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("O", "ユイ（アストラル）", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", 0, 128901, "ヒューマン", "トゥインクルウィッシュ", "戦闘のサポートが得意な、心優しい少女", 47, "料理、人間観察", 158, 2, "種田梨沙", 5, 4);
